	/**
	 * @return the address
	 */
	public Address getAddress() {
		return address;
	}

	/**
	 * @return the message
	 */
	public string getMessage() {
		return message;
	}

	public bool isError() {
		return status == BSimResultStatus.ERROR;
	}

	public bool isIgnored() {
		return status == BSimResultStatus.IGNORED;
	}

